import{_ as t,o,c as n,ag as s}from"./chunks/framework.CukOUUOK.js";const c=JSON.parse('{"title":"不可召集的多数：平台劳动中的法律形式供给与「人民」的位置","description":"以陈国江案为切入点提出\\"形式供给假说\\"：劳动者能否组织起来，首要取决于法律是否为集体行动提供合法且可预期的外壳。形式失灵有两种——\\"无壳\\"与\\"壳不可入\\"，后者更隐蔽，因为位上有人、位里无事。核心命题是\\"人民\\"在平台劳动中技术上被高度清点，而自我召集的通道缺位。","frontmatter":{"title":"不可召集的多数：平台劳动中的法律形式供给与「人民」的位置","categories":"政治思想史","tags":["劳动与经济","法治与宪法","权力","社会心理"],"description":"以陈国江案为切入点提出\\"形式供给假说\\"：劳动者能否组织起来，首要取决于法律是否为集体行动提供合法且可预期的外壳。形式失灵有两种——\\"无壳\\"与\\"壳不可入\\"，后者更隐蔽，因为位上有人、位里无事。核心命题是\\"人民\\"在平台劳动中技术上被高度清点，而自我召集的通道缺位。","date":"2026-09-24T12:00:00.000Z","series":"名与数：论权力对命名与点名的双重垄断","seriesOrder":4},"headers":[],"relativePath":"posts/2026-09-24-uncallable-majority.md","filePath":"posts/2026-09-24-uncallable-majority.md","lastUpdated":1790251379000}'),g={name:"posts/2026-09-24-uncallable-majority.md"};function a(p,r,e,l,i,h){return o(),n("div",null,[...r[0]||(r[0]=[s('<h1 id="不可召集的多数-平台劳动中的法律形式供给与「人民」的位置" tabindex="-1">不可召集的多数：平台劳动中的法律形式供给与「人民」的位置 <a class="header-anchor" href="#不可召集的多数-平台劳动中的法律形式供给与「人民」的位置" aria-label="Permalink to &quot;不可召集的多数：平台劳动中的法律形式供给与「人民」的位置&quot;">​</a></h1><h3 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h3><p>本文的起点是一个此前提出、后被本文推翻的判断。</p><p>那个判断是：<strong>当代平台劳动条件的改善主要来自法律与行政技术，而非阶级意识的觉醒</strong>，并由此把法律视为一个偏向劳动者的外生杠杆——它把外部化的成本记回资本的账上，劳动者可以借力。</p><p>本文推翻它，因为这一框架遗漏了关键一环：<strong>同一套法律同时是决定”多少人可以一起说话”的力量。</strong> 它既改善条款，也封锁形式。这一步不是补充，是改向——被推翻的那个判断及其三项派生方案，其仍成立的部分已在本文中重述，不再单独立篇。本文以陈国江（”外送江湖骑士联盟”）案为切入点，提出**“形式供给假说”**：劳动者能否组织起来，首要取决于法律是否为集体行动提供合法且可预期的外壳；在这一外壳缺位的条件下，”条款改善”与”组织缺席”并非两个巧合，而是同一治理取向的两面。</p><p>文章进一步把该假说补全为对称形式：形式失灵有两种，<strong>无壳</strong>（不提供合法形式）与<strong>壳不可入</strong>（形式存在，但供给权不在需求方手里）——后者更隐蔽，也更难通过”立法”本身解决。在此基础上，本文处理副标题所承诺的核心命题：<strong>“人民”在平台劳动中的真实位置，是技术上被高度清点，而自我召集的通道缺位</strong>（”完全不可召集”只对”无壳”情形成立；本文所考察情形的通道状态，按 4.3 节的分类逐项指认）。须说明：这不是卷一所处理术语的滑移终点——”人民”不在卷一的术语清单内；它是<strong>一条并置的独立证据</strong>，可直接观察，无需经由卷一的机制推出。</p><p>文章还区分”共谋”与”结构性收敛”两种解释并给出三条可观察的判别式，<strong>但本文未能裁定二者</strong>（所需数据为零或样本不足，判别式实为待执行的设计）。最后修正此前的三项方案，提出检验一个”壳”是否真实的<strong>三问判据</strong>，并论证可撤回性不仅是一种制度设计，更是一种风险分配。</p><p><strong>关键词</strong>：可召集性；可清点性；法律形式供给；壳不可入；平台劳动；集体行动；寻衅滋事；结构性收敛</p><h3 id="一、问题的重述-一个被遗漏的顶点" tabindex="-1">一、问题的重述：一个被遗漏的顶点 <a class="header-anchor" href="#一、问题的重述-一个被遗漏的顶点" aria-label="Permalink to &quot;一、问题的重述：一个被遗漏的顶点&quot;">​</a></h3><p>本卷一讨论术语滑移，结论是批判性概念被空心化为身份标记；卷二讨论平台经济，结论是当代劳动条件的改善主要来自法律与行政技术，并隐含地将法律视为劳动者可以借力的杠杆。这两篇合在一起，留下一个未解决的矛盾：如果改变确实来自条款而非运动，那么”人民”在这个过程中扮演什么角色？</p><p>此前的回答围绕”可被代表而不可召集”展开，但存在一处实质性偏差：我把法律写成了一个中立的放大器。我假设它只朝一个方向工作——把外部化的成本记回资本的账上。但同一套法律同时在做另一件事，而且方向相反：<strong>它决定什么样的聚集是合法的，什么不是。</strong> 忽略这一层，整组分析就是歪的。</p><p>因此必须补上三角形的第三个顶点。修正后的模型是：</p><p><strong>平台负责技术性的分散</strong>（算法个体化、考核个人化、雇主责任碎片化、聚集空间消失）； <strong>法律负责形式性的封锁</strong>（不提供合法的集体行动外壳，并对聚合行为施加不可预测的成本）； <strong>两者的目标函数不需要事先协调，就会收敛于同一个均衡——一个无法自行完成点名的对手方。</strong></p><p>（术语澄清：此处的”无法清点”指<strong>无法由劳动者自己清点并据此集合</strong>，不是指治理者不知道他们有多少人。恰恰相反，治理者的名册极其精确——见第五节。本卷此前在这两种含义间滑动，现统一为：<strong>清点有两个主语，治理者的清点是统计，被治者的清点是政治。</strong> 后文凡单用”清点”一词，均指后者，除非标明。）</p><p>这不是两个独立机制的叠加，而是一个系统的双重输出。下面先摆事实，再谈理论。</p><h3 id="二、经验材料-可核查的部分与待验证的部分" tabindex="-1">二、经验材料：可核查的部分与待验证的部分 <a class="header-anchor" href="#二、经验材料-可核查的部分与待验证的部分" aria-label="Permalink to &quot;二、经验材料：可核查的部分与待验证的部分&quot;">​</a></h3><p><strong>陈国江案</strong>。须先交代来源状态：下列事实来自媒体公开报道（含深度报道与新闻综述），<strong>本文未能逐一标注篇名，也无法提供一手材料</strong>。因此它们应被读作<strong>媒体综述性事实</strong>，可靠程度低于可核验的官方文本（对比卷三所引法条与政府文件）。本文的处理是：<strong>只用这些事实承重结论中最不涉及推论的部分</strong>（结果结构：诉求被接受、节点被移除），凡需推断因果处一律不作断言。</p><p>以下仅陈述公开报道可核实部分：</p><ul><li>2019年7月起，他通过在配送箱上贴二维码建群，逐步形成”外送江湖骑士联盟”，自称”盟主”。至2020—2021年间，联盟拥有十几个微信群，微信好友逾万人，绝大多数为骑手。活动内容包括协助被欠薪骑手拍摄视频讨薪、为被打骑手出头、提供临时落脚处、处理交通事故与合同纠纷互助。</li><li>2019年双十一前，因美团、饿了么同时下调单价，他在群内提议分片区轮流停送。行动尚未展开即告终止，他被北京警方刑事拘留26天。此后因有拘留记录被平台拉黑，失去骑手身份。</li><li>2021年2月18日，他发布视频指出饿了么春节奖励规则在第六周将门槛从约200单悄悄提高至380单。2月19日，饿了么公开致歉并整改。</li><li>2月25日被带走，3月17日家属收到刑事拘留通知书，4月2日正式逮捕，罪名寻衅滋事。联盟随后解散。</li><li><strong>关于案件的最终处置结果，我没有找到可靠的公开信息，不作断言。</strong></li></ul><p><strong>一处已移出正文的材料：</strong> 本文曾在此处保留一则对照材料（据澳洲媒体与智库报道：2026 年初悉尼华人骑手在微信群商议春节集体不接单后，有人接到国内老家派出所来电，警方通过其父母询问组织情况），并标注”不作为论据承重”。</p><p><strong>经复核，该处理不成立，该材料已从正文删除。</strong> 理由：一则材料若声明”不参与推论”，它在正文中就不再有论证功能；而它留在正文里的唯一效果，是让读者带着”跨国经由家属施压是普遍机制”这一暗示离开。<strong>形式免责与实质利用并存，比直接引用更不诚实。</strong> 该机制若值得研究，须另立专题并以可核实的信源支撑；本文不因其”看起来有力”而保留它。</p><p>以下论证仅使用上文已陈述的国内可核查材料。</p><p>若只陈述可观察的部分：本案中被移除的那个节点，其功能只有一个——<strong>让这个群体能够自己数出自己</strong>。至于”由谁决定移除”，本文没有材料回答，也不假定一个统一行动者。</p><p><strong>本案最值得反复读的是它的结果结构：饿了么道歉了，规则改了，人进去了。</strong></p><p>必须先把这句话的证明力说清楚，否则它会变成一句漂亮的空话。<strong>“道歉了”“规则改了”是公司行为（2 月 18 日视频→2 月 19 日公开致歉并整改）；”人进去了”是执法行为（2 月 25 日被带走，4 月 2 日逮捕）。两者在公开材料中分属不同行动者、不同程序。本文没有材料证明二者之间存在因果关联——逮捕所针对的可能是二月视频，也可能是此前已被刑事拘留过的整个联盟活动史。</strong></p><p>因此本文只主张可核查的那一部分：</p><blockquote><p><strong>改善与移除，在同一条时间线上的六天内先后发生。本文不断言其间的因果，只指出其时序。</strong></p></blockquote><p>时序本身已足以支撑本文要论证的东西——因为本文关心的不是”谁决定了什么”，而是<strong>结果的结构</strong>：诉求的内容被接受了，提出诉求的节点被移除了。<strong>要解释这个结果，不需要假定一个统一行动者。</strong> 两个各自追求自身目标的行动者，完全可以各自作出上述选择：公司接受一次性的条款调整（成本可计算、可分摊、可消化），执法机关移除一个不可控的召集节点。<strong>“谁在决策”这个问题本文无法回答；本文能回答的是”什么被留下了”。</strong></p><p>这也修正了本文的一处硬伤：”任何理性组织都会选择前者”这一表述——<strong>该句无主语，把公司与执法缝合为一个匿名的”系统”，而这恰恰是第七节要回答的问题，却在第七节之前被预设了。已删除。</strong></p><p>这也把此前”议程无权”的判断推进一层。那个判断是：改良停留在参数层面，结构层面保持封闭。现在可以补充：<strong>结构之所以封闭，不是因为参数不重要，而是因为任何试图把参数问题升级为结构问题的人，会从博弈中消失。</strong> 此处仍不预设原因——消失可能是被决定移除，也可能是另一程序的独立结果。<strong>本文主张的是现象，不是机制。</strong></p><h3 id="三、理论回溯-马克思从未把国家当作中立第三方" tabindex="-1">三、理论回溯：马克思从未把国家当作中立第三方 <a class="header-anchor" href="#三、理论回溯-马克思从未把国家当作中立第三方" aria-label="Permalink to &quot;三、理论回溯：马克思从未把国家当作中立第三方&quot;">​</a></h3><p>此前把国家写得像一个中立的调节器，这是我的失误。马克思本人从未如此认为，而且他的相关论述恰好构成了一个完整的序列：</p><p><strong>第一，《路易·波拿巴的雾月十八日》</strong>：国家具有相对独立性，能在阶级之间摆动，甚至凌驾于它们之上。一场工人革命最终选出皇帝，并非因为革命者愚蠢，而是因为国家是一个有自身利益和自身逻辑的行动者。</p><p><strong>第二，《黑格尔法哲学批判》</strong>：他对官僚制最持久的批评在于其<strong>冒充性</strong>——以普遍利益的名义行事，实际执行特殊利益，并且由于披着普遍性的外衣，这种特殊利益变得难以质询。这条判断的价值在于它对称：既能批评监管俘获，也能批评任何自称代表人民的行政体系。<strong>不能对称使用的理论，往往只是一种队服。</strong></p><p><strong>第三，《论犹太人问题》</strong>：政治解放不等于人的解放。国家可以在法律上宣布人人平等，同时让市民社会中的实际不平等原封不动。<strong>权利的文本化不构成胜利，只构成一个待检验的承诺。</strong></p><p><strong>第四，《法兰西内战》</strong>：他对公社的三项设计——代表随时可撤换、公职人员领取相当于工人的工资、兼管行政与立法的实干机构而非议会式机构——全部指向同一个目标：<strong>让代表权变成可回收的短期委托，而非一次性的权力让渡。</strong>（附带说明：马克思信任的不止可撤回性一项，他还坚持物质条件的约束；但就本文论题而言，可撤回性是最直接可用的判据。）</p><p>把这四层放在一起，马克思的真实立场十分清晰：他不信任代表制会自动兑现，也不信任行政技术会中立执行。他信任的只有一件事——<strong>可撤回性</strong>。谁能被撤换、谁能被质询、谁的账本能被翻开，权力就在哪里。</p><p>用这个判据衡量今天：<strong>条款可以撤回，但撤回的权力不在撤回者手里。</strong> 这便是全部问题的症结。</p><h3 id="四、核心命题-形式供给假说-补全版" tabindex="-1">四、核心命题：形式供给假说（补全版） <a class="header-anchor" href="#四、核心命题-形式供给假说-补全版" aria-label="Permalink to &quot;四、核心命题：形式供给假说（补全版）&quot;">​</a></h3><p>中国现行宪法没有规定罢工权（1975年、1978年宪法曾规定，1982年宪法取消）；集体协商的合法通道主要通过工会系统进行。其结果是：</p><p><strong>自发的集体行动在法律上没有可栖身的形式。</strong></p><h3 id="_4-1-同一行为-两个法域" tabindex="-1">4.1 同一行为，两个法域 <a class="header-anchor" href="#_4-1-同一行为-两个法域" aria-label="Permalink to &quot;4.1 同一行为，两个法域&quot;">​</a></h3><p>行为澳大利亚中国集体拒绝接单受保护的工业行动（industrial action），有专门框架、程序与豁免可能落入《治安管理处罚法》”聚众扰乱单位秩序”，或《刑法》寻衅滋事、聚众扰乱社会秩序这不是文化差异，这是<strong>形式供给的差异</strong>。英国有工会立法传统，德国有《基本法》第9条第3款的结社权保障，美国有《瓦格纳法》——这些法律并没有让劳资和谐，它们只是做了一件极朴素的事：<strong>把”组织”这件事从刑事领域挪到了民事与行政领域。</strong> 罪名仍在，争议仍在，但不确定性大幅下降了。</p><h3 id="_4-2-欧盟的绕道与它的代价" tabindex="-1">4.2 欧盟的绕道与它的代价 <a class="header-anchor" href="#_4-2-欧盟的绕道与它的代价" aria-label="Permalink to &quot;4.2 欧盟的绕道与它的代价&quot;">​</a></h3><p>欧盟《平台工作指令》用<strong>举证责任倒置</strong>这个技术手段绕过了”谁代表劳动者”这个政治难题——只要存在算法调度、评分奖惩等事实即推定雇佣关系，举证责任在平台。这是一种<strong>不需要主体在场就能生效</strong>的保护。</p><p><strong>一处时序自限必须写明</strong>：该指令 2024 年方才通过并进入成员国转化期，<strong>尚无充分的效果数据</strong>。因此本文”它不生产主体”的判断<strong>是一个预期，不是一项发现</strong>。可检验化表述如下：<strong>该路径在技术上绕开了主体，故其生效不要求主体生产；至于它是否会间接促进主体生成，须待转化期结束后以经验材料裁定。</strong></p><p>同时必须处理一个本文回避的规范预设：<strong>为什么”没有主体”是一种欠缺？</strong> 若劳动者的处境确实因该指令而改善，那么”不生产主体”为何构成批评？本文的回答是——<strong>这不是价值裁决，而是条件判断</strong>：不依赖主体在场的保护，其可持续性取决于规制者自身的持续意愿；它不能被撤回、被重申、被用作下一次议价的起点。<strong>本文不作”有主体的保护更高一等”的判断，只指出两者的存续条件不同。</strong></p><h3 id="_4-3-假说的补全-无壳-与壳不可入" tabindex="-1">4.3 假说的补全：无壳，与壳不可入 <a class="header-anchor" href="#_4-3-假说的补全-无壳-与壳不可入" aria-label="Permalink to &quot;4.3 假说的补全：无壳，与壳不可入&quot;">​</a></h3><p>以上是本文前稿已有的论证。但它隐含了一个未经检验的前提：形式失灵只有”无壳”一种。这是不完整的。真实世界至少有<strong>两种失灵</strong>，而且第二种更隐蔽：</p><p><strong>（一）无壳：法律不提供该形式。</strong> 没有罢工权、自发集体行动无合法定性——这是本文已论证的情形。它的表现是<strong>行为直接落入刑事或治安领域</strong>。</p><p><strong>（二）壳不可入：形式存在，但供给权不在需求方手里。</strong> 工会作为唯一的合法集体协商通道确实存在，但关键在于：<strong>基层工会的建立须报上一级工会批准。</strong> 这意味着劳动者不能自行生成一个合法的议价主体——<strong>壳必须由上面供给，不能被下面造出来。</strong> 于是”供给”这个词在这里呈现出它的全部重量：需求方有需求，供给方有权力，两者不是同一批人。</p><p><strong>（三）第三种可能：壳可入而无牙。</strong> 入口敞开，但既无对抗手段（无罢工权），又无可执行的议价工具，最终退化为服务与救济的提供者。这在功能上等价于”有壳等于无壳”，但在<strong>正当性上远高于无壳</strong>——因为它对外展示的是一个已被填满的位置。</p><p><strong>叠加解释是不可检验的</strong>——任何观察结果都能被归入其中一种或几种，假说的解释力以牺牲排他性为代价。本节因此改为逐条指认可核查的对应项：</p><p>失灵类型本文可指认的法条/事实依据尚缺经验验证的部分无壳1982 年宪法取消罢工自由条款；自发集体行动无合法定性—壳不可入《工会法》第十二条：基层工会建立须报上一级工会批准批准权在实践中被柔性行使的程度壳可入而无牙缺乏对抗手段；代表由推荐与自荐产生（详见卷三第七节）个案层面的实际议价效果这个补全对本文主论点是必要的：如果只谈”无壳”，批评者可以用一句话顶回来——”工会不是在那儿吗？”而补全之后，这句话反而成了证据：<strong>位置被填满了，功能却没被履行。</strong></p><p><strong>但必须同时承认</strong>：三种失灵的边界并不清晰，且本文<strong>没有</strong>给出”何种观察结果会排除其中某一种”的判别标准。因此本文只主张三种失灵<strong>在逻辑上可区分</strong>，不主张在具体个案中总能被唯一指认。</p><h3 id="_4-4-原子化的完整解释" tabindex="-1">4.4 原子化的完整解释 <a class="header-anchor" href="#_4-4-原子化的完整解释" aria-label="Permalink to &quot;4.4 原子化的完整解释&quot;">​</a></h3><p>因此，”原子化”不能只归咎于算法。<strong>算法制造了物理上的分散，法律上的不可预测性制造了心理上的分散</strong>，而”壳不可入”则取消了第三条路——你甚至无法通过”照规矩建一个组织”来绕过前两者。</p><p>须说明此处的方法论边界。<strong>叠加解释不可检验</strong>——任何结果都能被归入其中一种或几种，解释力以牺牲排他性为代价。因此本节三项应被读作<strong>并列的条件</strong>，而非可以相加的解释：本文主张它们各自可核查，不主张它们的和等于结果。4.3 节的表是<strong>逐条指认</strong>（哪一条失灵对应哪一项可核查依据），不是叠加模型；且本文<strong>没有</strong>给出”何种观察会排除其中某一种”的排除标准。三种失灵在逻辑上可区分，在个案中未必能被唯一指认。</p><h3 id="五、-人民-的三种在场-从空洞化到不可召集" tabindex="-1">五、”人民”的三种在场：从空洞化到不可召集 <a class="header-anchor" href="#五、-人民-的三种在场-从空洞化到不可召集" aria-label="Permalink to &quot;五、”人民”的三种在场：从空洞化到不可召集&quot;">​</a></h3><p>现在处理副标题承诺的那个命题。卷一说批判性词汇会被空心化为身份标记；本文要说，”人民”这个词的滑移走得更远——<strong>它没有停在空洞，而是停在了一个更精确的位置上：可清点，但不可召集。</strong></p><h3 id="_5-1-三种在场方式" tabindex="-1">5.1 三种在场方式 <a class="header-anchor" href="#_5-1-三种在场方式" aria-label="Permalink to &quot;5.1 三种在场方式&quot;">​</a></h3><p><strong>其一，统计在场。</strong> 平台劳动者被大量计数：注册骑手数、日均活跃数、完成订单数、入会人数。他们在每一个统计口径里都庞大、清晰、可加总。作为<strong>人口</strong>，他们是当代最容易被看见的群体之一。</p><p><strong>其二，话语在场。</strong> “人民”“劳动者”“新就业形态劳动者”“工人阶级”——这些词在政策文本、媒体报道与法律条文中被高频引用。作为<strong>正当性来源</strong>，他们无处不在。</p><p><strong>其三，程序缺席。</strong> 在任何一个需要”由他们自己提出、由他们自己决定、由他们自己撤回”的程序中，他们不在场。集体协商由既有组织代为进行；规则变更没有必须由劳动者同意的环节；算法调整没有强制的异议期。<strong>作为能够采取集体行动的主体，他们从未出现过。</strong></p><h3 id="_5-2-倒挂-被高度清点-而自我召集的通道缺位" tabindex="-1">5.2 倒挂：被高度清点，而自我召集的通道缺位 <a class="header-anchor" href="#_5-2-倒挂-被高度清点-而自我召集的通道缺位" aria-label="Permalink to &quot;5.2 倒挂：被高度清点，而自我召集的通道缺位&quot;">​</a></h3><p>这里出现本系列最需要命名的一个现象：</p><p><strong>平台劳动者在技术上被清点到了前所未有的精度</strong>——每一个个体都被算法完整记录：位置、时长、速度、评分、完成率。他们的可清点性是工业时代无法想象的。</p><p><strong>但自我召集的通道缺位</strong>——没有任何一个合法的、可预期的、有边界的程序，能让他们把这份被清点的事实，转化为一次共同的行动。</p><p>可清点性与可召集性在这里发生<strong>倒挂</strong>：前者被技术推到高点，后者被形式供给压到低点。<strong>而且，被清点恰恰不是被自己清点——清点是照料方完成的。你被谁清点，不意味着你能被自己召集。</strong></p><p><strong>一处论断强度的自限（重要）</strong>：本文称两者为”<strong>反向关系</strong>“（负相关）。<strong>本文撤回该表述。</strong> 单点观察支持”高清点＋零召集”的<strong>并存</strong>，不支持其间的函数关系——确立反向关系需要跨案例比较，须存在”清点少而召集多”的对照群体，而本文一个对照群体也没有。修正后的主张仅为：<strong>在特定结构下，清点的完成取消了”由被清点者自己集合”这一程序的必要性</strong>（主语是治理者；主语若换成被治者，该命题不成立——详见卷三 7.3 节对两种”必要性”的拆分）。</p><p>这正是马克思那句直觉的当代形态：他关心的从来不是”人民”这个词有多响，而是”人民”能不能作为一个可清点、可集合、可撤回委托的<strong>身体</strong>出现。<strong>一个只能被别人清点、不能被自己召集的多数，在政治意义上等于不存在。</strong></p><h3 id="_5-3-与卷一并置的一条证据" tabindex="-1">5.3 与卷一并置的一条证据 <a class="header-anchor" href="#_5-3-与卷一并置的一条证据" aria-label="Permalink to &quot;5.3 与卷一并置的一条证据&quot;">​</a></h3><p>由此可以给本系列的语言学线索补上一条并置的证据：</p><p>卷一处理的是资本主义、剥削、异化、市民社会、社会主义这批术语；<strong>“人民”不在卷一的清单里</strong>，因此本文不把下述现象说成卷一机制的终点。本文与卷一是<strong>并置的两条证据</strong>：<strong>“人民”一词的最终形态不是空洞化——空洞的词至少还占着一个位置；它的最终形态是被剥夺了可召集性：它在每一个载体上都被引用，在任何一个程序里都不真正在场。</strong></p><p>一个空洞的词，你还可以争论它是什么意思；一个被剥夺了可召集性的词，你连争论的入口都没有——因为没有任何程序需要它先被召集才能被代表。</p><p><strong>“空洞化”与”不可召集”因此不是同一条链条上的前后两段，而是两类不同的失效</strong>：前者是语言层的，后者是政治层的。卷一处理前者，本文处理后者，两者指向同一群人的处境，但不必互相推出——”人民”一词不在卷一所处理的术语清单内。</p><h3 id="六、机制细化-定价而非惩罚" tabindex="-1">六、机制细化：定价而非惩罚 <a class="header-anchor" href="#六、机制细化-定价而非惩罚" aria-label="Permalink to &quot;六、机制细化：定价而非惩罚&quot;">​</a></h3><p>寻衅滋事的条文极宽（聚众斗殴、追逐拦截他人、强拿硬要、在公共场所起哄闹事），学界与实务界长期称其为”口袋罪”。它在本案中的功能值得精确描述：</p><p><strong>它的要害不在于量刑多重，而在于边界不可预测。</strong></p><p>如果一个行为的罪与非罪取决于执法者的裁量，那么潜在组织者的风险计算就变成了：</p><blockquote><p>期望成本 = 被抓概率 × 后果</p></blockquote><p>而”被抓概率”这一项<strong>无法估计</strong>，因为它不取决于你是否违法，而取决于你被认定为”闹事”的可能性。</p><p>在这种定价结构下，理性的反应不是勇敢，而是退出。而且退出是<strong>选择性的</strong>：<strong>有组织能力与公共意愿的人，是退出成本最高、因而也最可能先退出的一类</strong>——他们的可替代性最低、被识别的概率最高，恰恰是这个群体最稀缺的部分。</p><p><strong>两处自限必须写明。</strong> 其一，无限量词与本文的材料规模不相称：<strong>本文只有一个案例，n=1 的材料配”永远”这类量词，不是机制研究的谨慎，是叙事的需要。</strong> 上段因此改述为一个可检验的预期：<em>在其他条件相同时，组织能力越强的人退出越早</em>——这是一个待检验的假设，不是已确立的规律。</p><p>其二，”<strong>按威慑效率最优设计</strong>的结构”这一表述——”最优设计”预设了一个设计者，这与本文第七节的结构性收敛立场直接冲突（若无需协调即可收敛，就没有设计者）。<strong>该表述已删除</strong>，改为：这是一种<strong>在威慑效率上表现最优的结构，无论其是否出自设计</strong>。效果可以描述，来源不可断言。</p><p>于是压制不需要大规模发生，它只需要偶尔发生且不可预测，就能产生持续的寒蝉效果。<strong>这是本文对”定价”机制的描述，其成立不依赖于对”谁在定价”的回答。</strong></p><h3 id="对称性-以免本文沦为单向指控" tabindex="-1">对称性（以免本文沦为单向指控） <a class="header-anchor" href="#对称性-以免本文沦为单向指控" aria-label="Permalink to &quot;对称性（以免本文沦为单向指控）&quot;">​</a></h3><p>在其他法域，压制采取的是不同但功能等价的形式——账号停用（deactivation）、反工会顾问产业、SLAPP 诉讼、英国《最低服务水准法》限制罢工范围、美国多州对工会活动的禁令。<strong>以上为常识性列举，本文未逐项引证；它只用于说明”形式不同”这一层，不承担论证重量。</strong> 差别在于法律形式与强度，不在于有无。 把中国的做法说成独一无二，会丧失比较分析的锋利度；把它说成”全世界都一样”，则会丧失批判的精确度。真实的判断在中间：<strong>形式不同，目标一致——让劳动者的集体行动尽可能昂贵、尽可能罕见、尽可能可被替代。</strong></p><h3 id="七、共谋-还是结构性收敛" tabindex="-1">七、共谋，还是结构性收敛？ <a class="header-anchor" href="#七、共谋-还是结构性收敛" aria-label="Permalink to &quot;七、共谋，还是结构性收敛？&quot;">​</a></h3><p>我不想用一个漂亮的结论收尾，因为这个问题还没到能下结论的时候。本节的目标因此降一档：<strong>不下结论，但给出判别式——如果将来有材料，它应该长什么样。</strong></p><p><strong>读法A：共谋。</strong> 平台与执法者协调行动。 <strong>读法B：结构性收敛。</strong> 两者各自追求自己的目标——平台要稳定的履约与可控的成本，执法要秩序与可预期——而”一个能独立召集逾万人的节点”恰好同时威胁这两个目标，于是不需要任何事先合谋，行为就会收敛于同一个均衡。</p><p><strong>先承认本文的设计错误</strong>：A 与 B 被设为互斥，实际上两者可以并存（收敛的结构上叠加共谋的插曲）。竞争假设的框架本身设计错了，本文保留二元对立仅为表述便利，<strong>不主张二者互斥</strong>。</p><p>三条可观察的判别式：</p><ol><li><strong>若A成立</strong>，应能观察到协调的痕迹：平台的信息提供与执法时点高度吻合、平台在争议中的具体诉求被逐条反映在处置方式上、同类行为在不同平台的处置因平台态度而异。</li><li><strong>若B成立</strong>，则应观察到<strong>模式对行动者的不敏感</strong>：换一家平台、换一批管理者、甚至在平台自身利益与秩序目标相冲突时，处置模式保持稳定。</li><li><strong>最强的一条</strong>：观察那些<strong>平台并不反对、甚至乐见</strong>的集体行动（如平台组织的骑手表彰、平台自建的沟通渠道）是否也被同等对待。若不被同等对待，说明被处置的对象不是”聚集”本身，而是**“独立于平台的聚集”<strong>——此时无论A还是B，均衡的落点都是那个</strong>不可被平台收编的召集节点**。</li></ol><p>第三条在设计上最有力，<strong>但必须坦白：本文没有提供任何一条”平台乐见的集体行动”的处置观察。判别式被提出、被称为尤其关键，然后被搁置了。</strong> 它在本文中的状态是<strong>待检验的设计</strong>，不是已执行的操作。</p><p><strong>两条判别式的可执行性同样须打折</strong>：判别式一（协调痕迹：信息提供与执法时点吻合）需要执法过程的内部信息，而本文连”最终处置结果”都无可靠信息，<strong>所需数据为零</strong>；判别式二（模式对行动者不敏感）需要反事实比较，样本量为一且材料不完整，<strong>n=1 无法检验不敏感性</strong>。</p><p>因此本节的实际产出必须被准确描述：<strong>它是一份研究设计，不是一项发现。</strong> 本文在此后默认 B 成立推进论证（”几何形状只能通过形式供给来改变”），<strong>这是未决问题被下游论证透支，已修正</strong>：下文第八节的方案设计不再以 B 为前提，而只以”两种读法都无法排除”为前提——<strong>若 A 成立，出路是追究具体协调行为；若 B 成立，出路是形式供给。两条路径互不排斥，可同时推进。</strong></p><p>还需承认一处：<strong>B 的弹性过大。</strong> 任何处置模式都可归因于”激励的几何形状”，这正是卷一第六节批判过的”能解释一切就预测不了任何具体事情”。<strong>本文不回避：结构性收敛这一解释在本文的使用中，尚未通过本文自己立下的可证伪性检验。</strong> 它被保留，是因为它比”共谋”更少需要无法获取的内部信息，而不是因为它更经得起检验。</p><p>形式供给这条路——为集体行动提供一个合法的、可预期的、有边界的壳——是本文方案的落点，<strong>但本文不主张它在两种读法下无条件成立</strong>。准确的表述是：它是两种路径的<strong>交集</strong>（见结论第四条），本文选择它，是因为它在证据不足的条件下仍然可推进，<strong>不是因为它已被证明是唯一解</strong>。</p><p>判别式三（平台乐见的集体行动是否被同等对待）在设计上最有力，但本文<strong>没有</strong>提供任何一条相关观察，也<strong>没有</strong>给出获取该观察的路径——一个连获取方案都没有的设计，与没有设计相差无几。本文据此把判别式三如实登记为<strong>待执行的设计</strong>，不把它计入本文的发现。</p><p>英德美花了半个多世纪、经历无数次流血才把这个壳做出来，而且至今仍在被削弱。</p><h3 id="八、修正后的三个方案-与一个三问判据" tabindex="-1">八、修正后的三个方案，与一个三问判据 <a class="header-anchor" href="#八、修正后的三个方案-与一个三问判据" aria-label="Permalink to &quot;八、修正后的三个方案，与一个三问判据&quot;">​</a></h3><h3 id="_8-1-先给判据-一个-壳-是真的吗" tabindex="-1">8.1 先给判据：一个”壳”是真的吗？ <a class="header-anchor" href="#_8-1-先给判据-一个-壳-是真的吗" aria-label="Permalink to &quot;8.1 先给判据：一个”壳”是真的吗？&quot;">​</a></h3><p>在评估任何方案之前，需要一套检验外壳真伪的工具。它与卷一检验术语死活的”三关”对称，但问的是制度而非词语：</p><ol><li><strong>能否不经许可进入？</strong>（准入）— 需要批准才能成立的主体，其存在本身就是被授予的。</li><li><strong>能否说”不”？</strong>（对抗）— 一个只能同意、不能拒绝的席位，不是议价席位，是咨询席位。</li><li><strong>说”不”之后能否存活？</strong>（存续）— 若对抗的代价由该主体独自承担且无法被制度吸收，那么第二问的”能”就是假的。</li></ol><p>用这三问量一下本文出现过的形态：</p><ul><li><strong>自发联盟</strong>（陈国江案）：第一问是、第二问是、<strong>第三问否</strong>——它死于第三关。</li><li><strong>既有工会通道</strong>：第一问部分（个体可入会，新组织不可自生）、第二问受限、第三问取决于层级——<strong>详见卷三第九节的逐项检验</strong>。</li></ul><p><strong>一项不成立的表述：”欧盟式推定——三问皆不适用，因为它压根不生产主体。”该条是循环论证，已删除。</strong> 循环在于：先用”主体缺席”解释三问不适用，再用”三问不适用”强化主体缺席。<strong>正确的表述是：三问判据对欧盟式推定确实不适用，但理由不是”它不生产主体”，而是——它根本不是一个”壳”。</strong> 三问检验的是主体能否形成并存续的机制；举证责任倒置是一条<strong>不经过主体的规则</strong>，两者不是同一类对象，判据本就不该套用。<strong>判据有其适用范围，越界使用会制造伪结论。</strong></p><p>这个判据的价值在于：它把”有没有组织”这个伪问题，换成了一个可分解的、可以逐项谈判的问题。<strong>你不必一次要到一个完整的工会，你可以先要第三问。</strong></p><h3 id="_8-2-三项方案-重新筛一遍" tabindex="-1">8.2 三项方案，重新筛一遍 <a class="header-anchor" href="#_8-2-三项方案-重新筛一遍" aria-label="Permalink to &quot;8.2 三项方案，重新筛一遍&quot;">​</a></h3><p><strong>方案一（重新发明可召集性）</strong>：必须承认，在当前法域下，瓶颈不在技术而在法律形式供给。因此真正有意义的实验不是”如何召集更多人”，而是”如何在现有合法外壳内长出实质议价力”——行业性协商要约、十人以上推举代表参加仲裁、算法备案后的公众评议参与、集体诉讼。诚实评估：<strong>这条路以安全性换效力。它的产出不要求主体在场——这不是”产不出主体”的价值判断，而是”不要求主体在场”的条件描述；至于长期是否间接生成主体，本文无材料裁定。</strong></p><p><strong>方案二（把代表性移到规制内部）</strong>：这条反而因本案得到了加强。既然公开召集的成本极高，那么制度化的席位——算法影响评估的劳动者代表、规则变更的异议期、自动化决策的人工复核权、审计结果强制披露——就成了几乎唯一的可持续入口，<strong>因为它不需要先成为一个”运动”。</strong> 这也是为什么此前那句”法律可以是运动的放大器”只对了一半：<strong>放大器本身不是中立的设施，谁掌握它，它就放大谁。</strong></p><p><strong>方案三（放弃”人民”，绘制问责链）</strong>：这条变得最为务实。问责链的好处在于，它把每一个环节都锚定在一个具名、可诉、可罚的行动者上，而不是寄托于一个随时可能被处理的符号。<strong>在”人民”不可召集的条件下，这是唯一不依赖主体在场而仍能推进的路径——但它同样不生产主体，因此它是止损，不是解法。</strong></p><p>三条的共同点没变：<strong>把不可撤回的委托，变成可撤回的委托。</strong> 但现在必须加上一条更冷的前提：</p><blockquote><p><strong>可撤回性不仅是一种制度设计，也是一种风险分配。如果撤回的代价全部落在撤回者身上，再精巧的设计也不会被使用。</strong></p></blockquote><p>这句必须写进任何一份制度建议书的第一页。它解释了为什么大量看起来很好的设计在真实世界里是死的：<strong>它们把撤回权给了最没有能力承担撤回后果的人。</strong></p><h3 id="九、结论" tabindex="-1">九、结论 <a class="header-anchor" href="#九、结论" aria-label="Permalink to &quot;九、结论&quot;">​</a></h3><p>本文的论证可压缩为四条：</p><p><strong>第一</strong>，此前框架的偏差在于把法律视为中立的放大器。补上”国家”这个顶点后，可观察的结果结构是：技术性分散与形式性封锁同时指向”被治者无法自行完成点名”这一状态。</p><p><strong>须提醒</strong>：第七节尚未裁定这种同时指向出自”共谋”还是”结构性收敛”——<strong>结论不预设答案</strong>。若出自共谋，责任可归于具体协调行为；若出自收敛，则责任分散于激励结构。本文只主张结果结构，不主张其生成机制。</p><p><strong>第二</strong>，”形式供给假说”成立且须补全为对称形式：劳动者能否组织起来，首要取决于法律是否为其提供合法且可预期的外壳；而失灵有两种——<strong>无壳</strong>与<strong>壳不可入</strong>，后者更隐蔽，因为位上有人、位里无事，看起来最像已经有了答案。</p><p>关于欧盟《平台工作指令》的举证责任倒置：该指令 2024 年方才通过并进入成员国转化期，<strong>尚无充分效果数据</strong>，因此本文不称其”成功”。本文的主张是一个<strong>预期</strong>：<strong>该路径在技术上绕开了主体，故其生效不要求主体生产。</strong> 至于它是否会间接促进主体生成，须待转化期结束后以经验材料裁定。</p><p>须一并说明：这不构成对该路径的价值降格。<strong>不依赖主体在场的保护，与依赖主体在场的保护，存续条件不同</strong>——前者取决于规制者的持续意愿，后者可被撤回、重申、用作下一次议价的起点。本文指出差别，不作高下裁决。</p><p><strong>第三</strong>，压制的精确机制是<strong>定价而非惩罚</strong>：通过边界不可预测的规范，使潜在组织者的风险无法估计，从而引发选择性退出。<strong>其预期效果是组织能力的优先流失——这是待检验的假设，本文 n=1 的材料不足以确立它。</strong> 而”人民”在其中的真实位置，是<strong>被高度清点、而自我召集通道缺位</strong>——这是一个独立可观察的主张，不从卷一的术语滑移推出：<strong>不是空洞化，而是被剥夺了可召集性。</strong></p><p><strong>第四</strong>，”共谋”与”结构性收敛”两种解释<strong>本文未能裁定</strong>，且第七节已承认所需数据为零或样本不足。本文能主张的只是：<strong>两种解释下，形式供给都是必要条件</strong>——若出自共谋，追究协调行为仍需一个合法的集体行动形式作为落点；若出自收敛，改变激励几何形状亦需该形式。形式供给因此是两种路径的交集，而不是某一解释的推论。</p><p>而检验一个壳是否真实，只需三问：<strong>能否不经许可进入、能否说不、说不之后能否存活。</strong></p><p>最后一个问题留给读者，因为它比任何结论都更接近真相：</p><p><strong>在没有这个壳的地方，劳动者除了等待壳被造出来，还能做什么？而历史上所有”壳”的诞生，有哪一次不是先有人在没有壳的情况下采取了行动？</strong></p><p>这是一个循环，不是一个答案。陈国江那逾万名骑手，就是这个循环在今天的肉身版本。他们失败了，联盟解散了，人也进去了。</p><p>而本案真正可核查的，不是一次成功的停送，而是<strong>一个六天的时间序列</strong>：2021 年 2 月 18 日，他发布视频指出饿了么春节奖励规则在第六周将门槛从约 200 单提高至 380 单；2 月 19 日，饿了么公开致歉并整改；2 月 25 日，他被带走。<strong>诉求在一天内被接受，提出诉求的人在一周内被移除。</strong></p><p>这三个点不在三篇报道里，而在同一条时间线上。<strong>改善与移除的同时发生，是本案唯一不需要推论即可读出的事实。</strong> 至于”订单是否真的没人接”——本文没有可靠材料，因此不作此断言；本文曾写下”在那几天，北京的外卖订单没人接”一句，经核无公开来源支持，且与本文第二节自述的”2019 年行动尚未展开即告终止”相冲突，<strong>已删除</strong>。一句没有来源的话，即使它比整篇论证都更像结论，也不能留在收尾处。</p><p><strong>马克思的原意不是”人多就有力量”——他从不相信概念能解放谁，他只相信能被清点的人数。</strong></p><p>而本文要补上的是：能被清点，还不够。<strong>要能被自己清点，并且能被自己召集。前者是统计，后者才是政治。</strong></p><hr><blockquote><p>本文同步自知乎，<a href="https://zhuanlan.zhihu.com/p/2086511324352270874" target="_blank" rel="noreferrer">查看原文</a></p></blockquote>',135)])])}const u=t(g,[["render",a]]);export{c as __pageData,u as default};
